import json,freya
r=json.load(open('results/a-run3.json'))
row=[x for x in r['rows'] if x['id']=='PUB-10'][0]
c=freya.get_call(row['call_id'])
ms=c.get('messages',[])
for i,m in enumerate(ms):
  t=str(m.get('message') or '')
  if 'function_call_error' in t:
    print(t[:400])
    for m2 in ms[i+1:i+3]:
      t2=m2.get('message') or ''
      if 'variable_table' in t2:
        vt=json.loads(t2)['variable_table']
        for k,v in vt.items():
          if 'promise' in k: print(k, v if not isinstance(v,dict) else v.get('value'))
    break
for m in ms:
  if m.get('role') in ('assistant','user'): print(m['role'],':',m.get('message'))
